
public class MO3L11LoopsConditions {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

	int total = 0;
	int counter = 0;
	
	for (int sum = 1; sum <= 5; sum++)
	{
		counter = counter + 1;
		total = total + counter;
		System.out.println("Counter: " + counter);
		System.out.println("Total: " + total);
	}
	}
}
